<style>
    .appraisal-modern{--ink:#26384f;--navy:#17375f;--teal:#246d68;--gold:#b77a38;--line:#e5ebf2;max-width:1440px;margin:0 auto;padding-bottom:48px;color:var(--ink)}
    .appraisal-modern .appraisal-hero{position:relative;overflow:hidden;margin-bottom:20px;padding:clamp(28px,4vw,48px)!important;border:0;border-radius:23px;color:#fff;background:linear-gradient(125deg,#17375f 0%,#184b69 62%,#9b6834 145%);box-shadow:0 20px 48px rgba(30,48,70,.15)}
    .appraisal-modern .appraisal-hero h1,.appraisal-modern .appraisal-hero h2{color:#fff;font-size:clamp(29px,3vw,42px);font-weight:750;line-height:1.1;letter-spacing:-.035em}
    .appraisal-modern .appraisal-hero p{color:#d7e5ed;line-height:1.65}
    .appraisal-modern .panel-card{overflow:hidden;margin-bottom:21px;border:1px solid var(--line);border-radius:19px;background:#fff;box-shadow:0 12px 30px rgba(25,48,77,.06)}
    .appraisal-modern .panel-card>.section-heading{display:flex;align-items:center;gap:14px;padding:20px 24px;border-bottom:1px solid #e8edf2;color:#183251;background:#fff}
    .appraisal-modern .panel-card>.section-heading h2,.appraisal-modern .panel-card>.section-heading h4{margin:0;color:#183251;font-size:19px;font-weight:750}
    .appraisal-modern .appraisal-section-card{overflow:hidden;margin:0 0 18px!important;border:1px solid #eadcc7;border-radius:16px;background:#fffaf2;box-shadow:0 8px 22px rgba(75,55,35,.04)}
    .appraisal-modern .appraisal-section-card:nth-child(even){border-color:#d9e7e2;background:#f7fbf9}
    .appraisal-modern .appraisal-section-card>.section-heading{margin:0;padding:15px 18px;border-bottom:1px solid rgba(155,111,57,.13);background:rgba(238,214,174,.48)}
    .appraisal-modern .appraisal-section-card:nth-child(even)>.section-heading{background:#e8f3ef}
    .appraisal-modern .appraisal-section-card>.section-heading h4{color:#3e3327;font-size:15px;font-weight:800}
    .appraisal-modern .subsection-block{margin-bottom:13px;padding:17px;border:1px solid rgba(180,154,119,.2);border-radius:13px;background:rgba(255,255,255,.87)}
    .appraisal-modern .subsection-heading{margin:0 0 14px!important;padding:0 0 0 12px;border:0;border-left:3px solid #c68d4c;border-radius:0;background:transparent}
    .appraisal-modern .subsection-heading h5{color:#4a3a2c;font-size:13px;font-weight:800}
    .appraisal-modern .appraisal-question-label{margin-bottom:7px;color:#405269;font-size:11px;font-weight:750;line-height:1.45}
    .appraisal-modern .appraisal-control{width:100%;min-height:42px;padding:10px 12px;border:1px solid #d9d4cb;border-radius:9px;color:#26384f;background:#fff;box-shadow:none;font-size:12px}
    .appraisal-modern textarea.appraisal-control{min-height:100px}
    .appraisal-modern .appraisal-control:focus{border-color:#b47a3d;box-shadow:0 0 0 3px rgba(180,122,61,.13)}
    .appraisal-modern .appraisal-control:disabled{color:#607185;background:#f4f5f4;opacity:1}
    .appraisal-modern .appraisal-readonly-answer{border-color:#d9d4cb;border-radius:9px;color:#26384f}
    @media(max-width:600px){.appraisal-modern .appraisal-hero{padding:25px 21px!important;border-radius:17px}.appraisal-modern .panel-card>.section-heading{padding:17px}.appraisal-modern .subsection-block{padding:13px}}
</style>
